// 同じ1600frame・100commitを正常終了まで保存し、本文byteと実Write/Sync回数を照合する。
package store

import (
 "bytes"
 "crypto/sha256"
 "encoding/binary"
 "encoding/json"
 "fmt"
 "os"
 "testing"

 "oimobbs/internal/domain"
)

func TestThreadGroupIOProbe(t *testing.T) {
 g, batches, create := newThreadGroupTest(t)
 for key := uint64(4); key <= 16; key++ {
  log, err := CreateThread(g.parent, g.owner, key, create)
  if err != nil { t.Fatal(err) }
  t.Cleanup(func(){ log.Close() })
  batches = append(batches, ThreadAppend{Log:log})
 }
 before := make([]CommitStats,len(batches))
 for i,b := range batches { before[i] = b.Log.CommitStats() }
 input := sha256.New()
 for seq := uint32(2); seq <= 101; seq++ {
  raw := packReply(t,create,seq)
  f,_,err := ReadFrame(bytes.NewReader(raw));if err != nil {t.Fatal(err)}
  f.Records[0].ID = domain.ID{42}
  binary.LittleEndian.PutUint64(f.Records[0].ID[8:],uint64(seq))
  raw,err=EncodeFrame(f);if err != nil {t.Fatal(err)}
  input.Write(raw)
  for i:=range batches { batches[i].Frames=[][]byte{raw} }
  if r:=g.Commit(batches);r.Status!=Durable {t.Fatal(r)}
 }
 if err:=g.Close();err!=nil {t.Fatal(err)}
 var writes,syncs,size uint64
 hashes:=map[string]string{}
 for i,b:=range batches {
  if b.Log.State().Revision!=101 {t.Fatal("lost committed frames")}
  s:=b.Log.CommitStats();writes+=s.Writes-before[i].Writes;syncs+=s.Syncs-before[i].Syncs;size+=s.Bytes-before[i].Bytes
  raw,err:=os.ReadFile(b.Log.file.Name());if err!=nil {t.Fatal(err)}
  hashes[fmt.Sprint(b.Log.header.Key)]=fmt.Sprintf("%x",sha256.Sum256(raw))
 }
 result:=map[string]any{"posts":1600,"commits":100,"input_sha256":fmt.Sprintf("%x",input.Sum(nil)),"body_write_calls":writes,"body_sync_calls":syncs,"body_written_bytes":size,"group_sync_calls":g.Stats().Syncs,"body_sha256":hashes}
 raw,err:=json.Marshal(result);if err!=nil {t.Fatal(err)}
 t.Log("IO_PROBE "+string(raw))
}

