   }
   await page.screenshot({path:'/home/patatan/OimoBBS/var/posting-io-bounded-20261025/'+file.replaceAll('/','-')+'-'+width+'.png'});
  }
  await page.goto(base+'/docs/testing/posting-io-checkpoint.md');
  await page.locator('table').first().scrollIntoViewIfNeeded();
  await page.screenshot({path:'/home/patatan/OimoBBS/var/posting-io-bounded-20261025/io-table-'+width+'.png'});
  await page.goto(base+'/docs/testing/measurements.md');
  await page.getByRole('link',{name:'保存待ちとcheckpointの削減',exact:true}).click();
  if(!page.url().endsWith('/posting-io-checkpoint.md'))throw new Error('Wrong report');
  clicks++;
  await page.close();
 }
